    return { ...base, result: expression(terms, parameters), callEffects: 'none', status: 'supported' };
  } catch (gap) {
    return { ...base, gap: { reason: gap.reason ?? 'UnsupportedExpression', span: body[0]?.span ?? null } };
  }
